engineering.schemaTypescript:
export type TripStatus = 'active' | 'ended';
export type QueueItemStatus = 'queued' | 'playing' | 'played' | 'skipped';
export type VoteValue = 1 | -1;

export interface Trip {
  id: string;
  host_id: string | null;
  code: string;
  qr_code_url: string | null;
  status: TripStatus;
  created_at: string;
  ended_at: string | null;
}

export interface Participant {
  id: string;
  trip_id: string;
  display_name: string;
  is_host: boolean;
  session_token: string | null;
  spotify_user_id: string | null;
  joined_at: string;
  left_at: string | null;
}

export interface Track {
  id: string;
  spotify_track_id: string;
  title: string;
  artist: string;
  album: string | null;
  duration_ms: number;
  genre: string | null;
  image_url: string | null;
  cached_at: string;
}

export interface QueueItem {
  id: string;
  trip_id: string;
  track_id: string;
  added_by: string;
  status: QueueItemStatus;
  fairness_score: number;
  vote_score: number;
  reason: string | null;
  position: number | null;
  created_at: string;
  played_at: string | null;
}

export interface Vote {
  id: string;
  queue_item_id: string;
  participant_id: string;
  value: VoteValue;
  created_at: string;
}

export interface PlaybackState {
  trip_id: string;
  current_queue_item_id: string | null;
  is_playing: boolean;
  progress_ms: number;
  updated_at: string;
}

export interface QueueItemWithDetails extends QueueItem {
  track: Track;
  added_by_name: string;
}

export interface Trip {
  id: string;
  hostUserId: string | null;
  joinCode: string;
  name: string;
  vibePrompt: string | null;
  status: 'active' | 'ended';
  spotifyAccessToken: string | null;
  spotifyRefreshToken: string | null;
  spotifyTokenExpiresAt: string | null;
  createdAt: string;
  endedAt: string | null;
}

export interface Participant {
  id: string;
  tripId: string;
  displayName: string;
  deviceId: string;
  spotifyUserId: string | null;
  isHost: boolean;
  joinedAt: string;
  leftAt: string | null;
}

export type QueueItemStatus = 'queued' | 'playing' | 'played' | 'skipped' | 'removed';

export interface QueueItem {
  id: string;
  tripId: string;
  addedBy: string | null;
  spotifyTrackId: string;
  trackName: string;
  artistName: string;
  albumArtUrl: string | null;
  durationMs: number | null;
  status: QueueItemStatus;
  fairnessScore: number;
  position: number | null;
  addedAt: string;
  playedAt: string | null;
}

export interface Vote {
  id: string;
  queueItemId: string;
  participantId: string;
  value: 1 | -1;
  createdAt: string;
}

export interface PlaybackState {
  tripId: string;
  currentQueueItemId: string | null;
  positionMs: number;
  isPlaying: boolean;
  updatedAt: string;
}

export type TasteSignalType = 'add' | 'upvote' | 'downvote' | 'skip' | 'play_complete';

export interface TasteSignal {
  id: string;
  tripId: string;
  participantId: string | null;
  spotifyTrackId: string;
  signalType: TasteSignalType;
  weight: number;
  createdAt: string;
}

export interface TripSummary {
  id: string;
  tripId: string;
  recapData: Record<string, unknown>;
  createdAt: string;
}

export interface Trip {
  id: string;
  code: string;
  hostParticipantId: string | null;
  name: string | null;
  status: 'active' | 'ended';
  balancingWeights: { recency: number; votes: number; genre: number; artist: number };
  createdAt: string;
  endedAt: string | null;
}

export interface Participant {
  id: string;
  tripId: string;
  displayName: string;
  isHost: boolean;
  tasteSignals: Record<string, unknown> | null;
  joinedAt: string;
}

export interface Track {
  id: string;
  tripId: string;
  externalId: string;
  title: string;
  artist: string | null;
  genre: string | null;
  durationSeconds: number | null;
  addedBy: string | null;
  status: 'queued' | 'playing' | 'played' | 'removed';
  score: number;
  playOrder: number | null;
  addedAt: string;
  playedAt: string | null;
}

export interface Vote {
  id: string;
  trackId: string;
  participantId: string;
  value: 1 | -1;
  createdAt: string;
}

export interface TripSummary {
  id: string;
  tripId: string;
  summaryText: string | null;
  topGenres: Record<string, number> | null;
  topArtists: Record<string, number> | null;
  createdAt: string;
}

export interface User {
  id: string;
  email: string;
  display_name?: string;
  created_at: string;
}

export interface BankAccount {
  id: string;
  user_id: string;
  bank_name: string;
  account_type: string;
  balance: number;
  as_of_date: string;
  created_at: string;
}

export interface Loan {
  id: string;
  user_id: string;
  loan_type: string;
  principal: number;
  interest_rate_pct: number;
  tenure_months: number;
  start_date: string;
  outstanding_balance: number;
  emi_amount?: number;
  created_at: string;
}

export interface SalaryStructure {
  id: string;
  user_id: string;
  effective_date: string;
  basic: number;
  hra: number;
  special_allowance: number;
  bonus_annual: number;
  employer_pf_contribution: number;
  tax_regime: 'old' | 'new';
  created_at: string;
}

export interface CreditCard {
  id: string;
  user_id: string;
  card_name: string;
  credit_limit: number;
  current_outstanding: number;
  reward_rules: Record<string, unknown>;
  created_at: string;
}

export interface MutualFundHolding {
  id: string;
  user_id: string;
  fund_name: string;
  units: number;
  avg_nav: number;
  current_nav?: number;
  sip_amount?: number;
  as_of_date: string;
  created_at: string;
}

export interface StockHolding {
  id: string;
  user_id: string;
  ticker: string;
  market: 'domestic' | 'international';
  quantity: number;
  avg_price: number;
  current_price?: number;
  currency: string;
  as_of_date: string;
  created_at: string;
}

export interface VestingScheduleEntry {
  date: string;
  units: number;
}

export interface RSUGrant {
  id: string;
  user_id: string;
  grant_type: 'RSU' | 'ESOP';
  company: string;
  total_units: number;
  vested_units: number;
  grant_date: string;
  vesting_schedule: VestingScheduleEntry[];
  strike_price?: number;
  current_price?: number;
  currency: string;
  created_at: string;
}

export interface EPFAccount {
  id: string;
  user_id: string;
  current_balance: number;
  employee_monthly_contribution: number;
  employer_monthly_contribution: number;
  as_of_date: string;
  created_at: string;
}

export interface NPSAccount {
  id: string;
  user_id: string;
  current_balance: number;
  monthly_contribution: number;
  asset_allocation: Record<string, number>;
  as_of_date: string;
  created_at: string;
}

export interface ConversationThread {
  id: string;
  user_id: string;
  title?: string;
  created_at: string;
}

export interface CalculationLog {
  id: string;
  user_id: string;
  function_name: string;
  function_version: string;
  inputs: Record<string, unknown>;
  outputs: Record<string, unknown>;
  created_at: string;
}

export interface Message {
  id: string;
  thread_id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  calculation_log_id?: string;
  created_at: string;
}

export interface ToolCallResult {
  function_name: string;
  inputs: Record<string, unknown>;
  outputs: Record<string, unknown>;
}

export interface Profile {
  id: string;
  full_name?: string;
  phone?: string;
  created_at: string;
}

export interface Project {
  id: string;
  user_id: string;
  name: string;
  plot_width?: number;
  plot_length?: number;
  plot_area?: number;
  facing?: string;
  road_width?: number;
  vastu_preference: 'strict' | 'light' | 'none';
  status: 'draft' | 'generated' | 'paid';
  created_at: string;
  updated_at: string;
}

export interface IntakeResponse {
  id: string;
  project_id: string;
  question_key: string;
  answer: Record<string, unknown>;
  created_at: string;
}

export interface FloorPlan {
  id: string;
  project_id: string;
  version: number;
  bhk_count?: number;
  total_area?: number;
  layout_json: FloorPlanLayout;
  pdf_url?: string;
  is_current: boolean;
  created_at: string;
}

export interface FloorPlanLayout {
  plot: { width: number; length: number; facing: string };
  floors: { floor_number: number; rooms: RoomGeometry[] }[];
}

export interface RoomGeometry {
  room_type: string;
  width: number;
  length: number;
  position_x: number;
  position_y: number;
  orientation?: string;
  vastu_zone?: string;
}

export interface Room {
  id: string;
  floor_plan_id: string;
  room_type: string;
  floor_number: number;
  width?: number;
  length?: number;
  position_x?: number;
  position_y?: number;
  orientation?: string;
  vastu_zone?: string;
  created_at: string;
}

export interface DesignRationale {
  id: string;
  floor_plan_id: string;
  room_id?: string;
  category: 'orientation' | 'vastu' | 'parking' | 'climate' | 'family';
  rationale_text: string;
  created_at: string;
}

export interface ModelAsset {
  id: string;
  floor_plan_id: string;
  asset_type: 'dollhouse' | 'walkthrough';
  file_url: string;
  format: string;
  created_at: string;
}

export interface Revision {
  id: string;
  project_id: string;
  floor_plan_id: string;
  change_summary?: string;
  created_at: string;
}

export interface Order {
  id: string;
  user_id: string;
  project_id: string;
  amount: number;
  currency: string;
  status: 'pending' | 'paid' | 'failed' | 'refunded';
  payment_provider?: string;
  payment_reference?: string;
  created_at: string;
}

export interface VastuRule {
  id: string;
  room_type: string;
  preferred_zone: string;
  priority: number;
  description?: string;
}

export interface Profile {
  id: string;
  email: string;
  full_name?: string | null;
  created_at: string;
}

export interface Brand {
  id: string;
  user_id: string;
  name: string;
  status: 'draft' | 'generating' | 'active';
  vibe_summary?: string | null;
  created_at: string;
  updated_at: string;
}

export interface FounderBrief {
  id: string;
  brand_id: string;
  what_it_does: string;
  target_audience: string;
  desired_vibe: string;
  raw_answers: Record<string, unknown>;
  created_at: string;
}

export interface BrandAsset {
  id: string;
  brand_id: string;
  asset_type: 'logo' | 'palette' | 'typography';
  file_url?: string | null;
  metadata: Record<string, unknown>;
  version: number;
  created_at: string;
}

export interface DesignToken {
  id: string;
  brand_id: string;
  token_category: 'color' | 'typography' | 'spacing' | 'radius';
  token_key: string;
  token_value: string;
  created_at: string;
}

export interface AssetRequest {
  id: string;
  brand_id: string;
  requested_by: string;
  request_type: 'social_post' | 'campaign_creative' | 'landing_page' | 'product_ui';
  prompt_text: string;
  status: 'queued' | 'processing' | 'completed' | 'failed';
  created_at: string;
  completed_at?: string | null;
}

export interface GeneratedAsset {
  id: string;
  asset_request_id: string;
  brand_id: string;
  file_url: string;
  preview_url?: string | null;
  format: 'png' | 'svg' | 'pdf' | 'figma-json';
  created_at: string;
}

export interface ExportJob {
  id: string;
  generated_asset_id?: string | null;
  brand_id: string;
  export_type: 'single_asset' | 'full_brand_kit';
  bundle_url?: string | null;
  status: 'pending' | 'ready' | 'failed';
  created_at: string;
}

export interface Subscription {
  id: string;
  user_id: string;
  stripe_customer_id?: string | null;
  stripe_subscription_id?: string | null;
  plan: 'free' | 'starter' | 'pro';
  status: 'active' | 'past_due' | 'canceled';
  current_period_end?: string | null;
  created_at: string;
}

export interface User {
  id: string;
  email: string;
  display_name?: string;
  created_at: string;
}

export type ElementType = 'fire' | 'water' | 'grass' | 'electric' | 'rock';

export interface Species {
  id: string;
  name: string;
  element_type: ElementType;
  base_attack: number;
  base_defense: number;
  base_speed: number;
  base_special: number;
  base_hp: number;
  catch_rate: number;
}

export type AbilityEffectType = 'steal_strat' | 'force_category' | 'ignore_type_disadvantage' | 'other';

export interface Ability {
  id: string;
  name: string;
  effect_type: AbilityEffectType;
  effect_config: Record<string, unknown>;
}

export interface SpeciesAbility {
  id: string;
  species_id: string;
  ability_id: string;
}

export interface CreatureInstance {
  id: string;
  owner_id: string | null;
  species_id: string;
  nickname?: string;
  level: number;
  xp: number;
  current_hp: number;
  is_active_roster: boolean;
  caught_at: string;
}

export interface Gym {
  id: string;
  name: string;
  element_type: ElementType;
  leader_species_id: string;
  order_index: number;
}

export interface Badge {
  id: string;
  user_id: string;
  gym_id: string;
  awarded_at: string;
}

export type BattleOpponentType = 'wild' | 'gym_leader' | 'ai_trainer';
export type BattleStatus = 'in_progress' | 'completed' | 'abandoned';

export interface Battle {
  id: string;
  player_id: string;
  opponent_type: BattleOpponentType;
  gym_id?: string | null;
  status: BattleStatus;
  winner_id?: string | null;
  started_at: string;
  ended_at?: string | null;
}

export type BattleSide = 'player' | 'opponent';

export interface BattleParticipant {
  id: string;
  battle_id: string;
  creature_instance_id: string;
  side: BattleSide;
  starting_hp: number;
}

export type StatCategory = 'attack' | 'defense' | 'speed' | 'special';

export interface BattleTurn {
  id: string;
  battle_id: string;
  turn_number: number;
  actor_side: BattleSide;
  stat_category_chosen: StatCategory;
  ability_triggered_id?: string | null;
  damage_dealt: number;
  was_type_advantaged: boolean;
  created_at: string;
}

export type BattleEventType = 'strategic_swing' | 'completion' | 'abandonment';

export interface BattleEvent {
  id: string;
  battle_id: string;
  event_type: BattleEventType;
  metadata: Record<string, unknown>;
  created_at: string;
}

export interface LeaderboardEntry {
  id: string;
  user_id: string;
  badge_count: number;
  win_count: number;
  updated_at: string;
}

export interface User {
  id: string;
  email: string;
  stripe_customer_id: string | null;
  created_at: string;
}

export interface Subscription {
  id: string;
  user_id: string;
  stripe_subscription_id: string | null;
  status: 'active' | 'past_due' | 'canceled' | 'trialing';
