  product_description: string | null;
  created_at: string;
}

export interface ProjectContext {
  id: string;
  project_id: string;
  readme_text: string | null;
  package_json_text: string | null;
  repo_url: string | null;
  extracted_features: Record<string, unknown>[];
  created_at: string;
}

export interface Asset {
  id: string;
  project_id: string;
  render_job_id: string | null;
  type: 'screenshot' | 'screen_recording' | 'logo' | 'final_video_16x9' | 'final_video_9x16' | 'thumbnail';
  storage_path: string;
  created_at: string;
}

export interface CaptionSegment {
  start: number;
  end: number;
  text: string;
}

export interface ShotListItem {
  order: number;
