}

export interface RenderJob {
  id: string;
  project_id: string;
  script_id: string;
  higgsfield_job_id: string | null;
  estimated_credit_cost: number | null;
  actual_credit_cost: number | null;
  status: 'pending_approval' | 'queued' | 'processing' | 'completed' | 'failed';
  error_message: string | null;
  created_at: string;
  completed_at: string | null;
}

export interface PublishingKit {
  id: string;
  render_job_id: string;
  title: string | null;
  description: string | null;
  hashtags: string[];
  created_at: string;
}
